// The whole message, loosely: case, punctuation, a leading "ok"/"well" and a
// trailing "Zoey" don't matter.
export function betaKey(text: string): string {
  return normalize(text)
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^(?:ok|okay|well|um|so) /, '')
    .replace(/(?: zoey?)+$/, '')
    .trim();
}

const INDEX = new Map<string, BetaEntry>();
for (const e of BETA) for (const s of e.said) if (!INDEX.has(betaKey(s))) INDEX.set(betaKey(s), e);

export function findBeta(text: string): BetaEntry | null {
  const k = betaKey(text);
  return k ? INDEX.get(k) ?? null : null;
}

const fill = (s: string, c: AnswerContext) => s.replace(/\{name\}/g, c.name);

// A beta answer shaped like a library answer, so the chat shows it the same way.
export function betaReply(text: string, c: AnswerContext): Extract<Reply, { kind: 'answer' }> | null {
  const e = findBeta(text);
  if (!e) return null;
  const answer: Answer = { id: e.id, topic: e.topic, q: e.said[0], keys: [], text: (x) => fill(e.reply, x) };
  return { kind: 'answer', answer, text: fill(e.reply, c), alts: e.alts.map((a) => fill(a, c)), actions: [], alternatives: [] };
}
